INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (390, 1, 'API 구성요소의 일', 'Nova 아키텍처 문서에서 **API 구성요소** 는 무슨 일을 한다고 할까요?', '요청을 받는 입구예요.', NULL, NULL, '[]', 'choice', '["인스턴스가 어느 호스트에 놓일지 직접 결정한다", "하이퍼바이저와 가상 머신을 직접 관리하며 돌아간다", "HTTP 요청을 받아 명령으로 바꿔 다른 구성요소에 전달한다", "자원 공급자의 재고와 사용량을 계속 추적한다"]', 2, '문서는 API 가 HTTP 요청을 받아 명령으로 변환하고 oslo.messaging 큐 또는 HTTP 로 다른 구성요소와 통신하는 요소라고 설명합니다. 호스트 결정은 스케줄러, 하이퍼바이저 관리는 컴퓨트의 일입니다.', NULL, NULL, NULL, '[{"title": "Nova 시스템 아키텍처", "url": "https://docs.openstack.org/nova/latest/admin/architecture.html"}]'),
  (390, 2, '스케줄러의 일', 'Nova 의 **스케줄러** 구성요소는 무엇을 결정할까요?', '이름 그대로 배치를 정해요.', NULL, NULL, '[]', 'choice', '["어느 사용자가 서버를 만들 수 있는지", "각 인스턴스가 어느 호스트에 놓일지", "이미지 데이터를 어느 스토어에 저장할지", "인스턴스의 비밀번호를 어떻게 바꿀지"]', 1, '문서는 스케줄러를 "어느 호스트가 각 인스턴스를 받을지 결정하는" 구성요소로 설명합니다. 인증과 권한은 Keystone, 이미지 저장은 Glance 의 영역입니다.', NULL, NULL, NULL, '[{"title": "Nova 시스템 아키텍처", "url": "https://docs.openstack.org/nova/latest/admin/architecture.html"}]'),
  (390, 3, '컴퓨트의 일', 'Nova **컴퓨트** 구성요소는 어디에서 무엇을 할까요?', '하이퍼바이저가 있는 곳이에요.', NULL, NULL, '[]', 'choice', '["관리하는 하이퍼바이저 쪽에서 돌며 VM 과의 통신을 맡는다", "컨트롤러 노드에서만 돌며 API 요청을 받아 준다", "데이터베이스를 직접 열고 모든 노드의 상태를 적는다", "네트워크 포트를 만들고 IP 를 나누어 주는 일을 한다"]', 0, '문서는 컴퓨트 프로세스가 보통 자신이 관리하는 하이퍼바이저에서 실행된다고(VMware·Ironic 드라이버는 예외) 설명합니다. 컴퓨트의 DB 접근은 콘덕터가 대신합니다.', NULL, NULL, NULL, '[{"title": "Nova 시스템 아키텍처", "url": "https://docs.openstack.org/nova/latest/admin/architecture.html"}]'),
  (390, 4, '콘덕터의 일', 'Nova **콘덕터** 가 맡는 일로 문서가 드는 것은 무엇일까요?', '조율과 DB 중개예요.', NULL, NULL, '[]', 'choice', '["VNC 콘솔 화면을 브라우저로 보내 주는 일을 한다", "이미지를 내려받아 루트 디스크로 변환해 주는 일을 한다", "모든 서비스의 토큰을 발급하고 검증해 주는 일을 한다", "빌드·리사이즈 같은 조율을 맡고 DB 프록시 역할을 한다"]', 3, '문서는 콘덕터를 빌드·리사이즈처럼 조율이 필요한 요청을 처리하고, 데이터베이스 프록시로 동작하고, 오브젝트 변환을 맡는 요소로 설명합니다.', NULL, NULL, NULL, '[{"title": "Nova 시스템 아키텍처", "url": "https://docs.openstack.org/nova/latest/admin/architecture.html"}]'),
  (390, 5, '컴퓨트의 DB 접근', '컴퓨트 노드의 서비스가 **데이터베이스에 접근하는 방식** 은 무엇일까요?', '직접 열지 않아요.', NULL, NULL, '[]', 'choice', '["모든 컴퓨트 노드가 DB 에 직접 연결해 읽고 쓴다", "컴퓨트 노드마다 로컬 DB 를 두고 서로 동기화한다", "DB 요청을 RPC 로 콘덕터에 넘겨 대신 처리하게 한다", "Keystone 을 거쳐 DB 의 읽기 복제본을 쓴다"]', 2, '문서는 컴퓨트 노드의 서비스가 DB 요청을 RPC 로 콘덕터에 프록시하며, 그 덕분에 업그레이드된 컨트롤 플레인이 이전 릴리스의 컴퓨트 노드와도 통신할 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Nova 시스템 아키텍처", "url": "https://docs.openstack.org/nova/latest/admin/architecture.html"}]'),
  (390, 6, '내부 통신 방식', 'Nova 내부 구성요소 사이의 **RPC 메시징** 은 무엇으로 이루어질까요?', '큐 위에 얹은 추상화 라이브러리예요.', NULL, NULL, '[]', 'choice', '["구성요소끼리 SSH 로 직접 명령을 실행한다", "oslo.messaging 라이브러리(메시지 큐 위의 추상화)", "공유 NFS 디렉터리의 파일을 서로 읽는다", "Glance 가 중개하는 이벤트 스트림을 쓴다"]', 1, '문서는 RPC 메시징이 메시지 큐 위의 추상화인 oslo.messaging 라이브러리로 이루어진다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Nova 시스템 아키텍처", "url": "https://docs.openstack.org/nova/latest/admin/architecture.html"}]'),
  (390, 7, '셀의 의미', 'Nova 문서에서 **셀(cell)** 은 무엇일까요?', '규모를 나누는 개념이에요.', NULL, NULL, '[]', 'choice', '["배포를 샤딩하는 개념이며 배포마다 최소 하나 있다", "서버 한 대 안의 CPU 코어를 묶은 단위", "인스턴스 하나에 붙는 디스크 하나의 단위", "프로젝트 하나가 쓰는 네트워크 구간"]', 0, '문서는 셀을 배포를 샤딩하는 개념이라고 하며, 모든 배포에는 적어도 하나의 셀이 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Nova 시스템 아키텍처", "url": "https://docs.openstack.org/nova/latest/admin/architecture.html"}]'),
  (390, 8, 'Placement 가 추적하는 것', '**Placement** 가 추적하는 것은 무엇일까요?', '재고와 사용량이에요.', NULL, NULL, '[]', 'choice', '["인스턴스 안의 프로세스 목록", "사용자의 로그인 기록", "이미지의 변경 이력", "자원 공급자의 인벤토리와 사용량"]', 3, '아키텍처 문서는 Placement 를 자원 공급자(resource provider)의 인벤토리와 사용량을 추적하는 구성요소로 설명합니다.', NULL, NULL, NULL, '[{"title": "Nova 시스템 아키텍처", "url": "https://docs.openstack.org/nova/latest/admin/architecture.html"}]'),
  (390, 9, '컴퓨트 호스트의 자원 공급자', 'Placement 에서 **컴퓨트 호스트 하나** 는 누가 어떻게 등록할까요?', '컴퓨트 안의 리소스 트래커예요.', NULL, NULL, '[]', 'choice', '["관리자가 호스트마다 손으로 레코드를 만들어야 한다", "Keystone 이 호스트 목록을 보고 자동으로 만들어 준다", "nova-compute 의 리소스 트래커가 호스트별로 만든다", "스케줄러가 인스턴스를 처음 배치할 때 그 자리에서 만든다"]', 2, 'Placement 문서는 nova-compute 의 리소스 트래커가 컴퓨트 호스트마다 자원 공급자를 만들고, Neutron·Cyborg 같은 다른 프로젝트는 그 아래에 자식 공급자를 만든다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Placement 사용자 문서", "url": "https://docs.openstack.org/placement/latest/user/index.html"}]'),
  (390, 10, '메시징 라이브러리', 'Nova 의 RPC 메시징에 쓰이는 라이브러리입니다. 빈칸을 채우세요.', '"oslo." 로 시작해요.', NULL, NULL, '[]', 'fill', '["oslo.messaging", "oslo.config", "oslo.policy", "oslo.db"]', NULL, 'RPC 메시징은 메시지 큐 위의 추상화인 oslo.messaging 으로 이루어집니다. oslo.config 는 설정, oslo.policy 는 권한 정책, oslo.db 는 DB 접근 라이브러리입니다.', '[0]', '{0}', NULL, '[{"title": "Nova 시스템 아키텍처", "url": "https://docs.openstack.org/nova/latest/admin/architecture.html"}]'),
  (390, 11, '공급자의 질적 특성', 'Placement 에서 자원 공급자의 **질적 특성** 을 나타내는 것입니다(예: STORAGE_DISK_SSD). 빈칸을 채우세요.', '양이 아니라 성질이에요.', NULL, NULL, '[]', 'fill', '["trait", "inventory", "allocation", "aggregate"]', NULL, 'Placement 문서는 trait 를 자원의 질적 특성으로 설명하며 STORAGE_DISK_SSD 를 예로 듭니다. inventory 는 VCPU 같은 양적 자원입니다.', '[0]', '{0}', NULL, '[{"title": "Placement 사용자 문서", "url": "https://docs.openstack.org/placement/latest/user/index.html"}]'),
  (390, 12, '서버 생성 요청이 흐르는 순서', '서버 하나를 만들 때 요청이 거치는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '입구 → 후보 → 배치 → 실행이에요.', NULL, NULL, '[]', 'order', '["API 가 HTTP 요청을 받아 명령으로 바꾼다", "스케줄러가 Placement 에서 할당 후보를 받는다", "필터와 가중치로 후보를 줄이고 순서를 매겨 호스트를 정한다", "선택된 호스트의 컴퓨트가 하이퍼바이저로 인스턴스를 만든다"]', NULL, 'API 가 요청을 받고, 스케줄러가 Placement 에 할당 후보를 요청한 뒤 필터와 가중치로 좁혀 호스트를 정하며, 컴퓨트가 실제 인스턴스를 만듭니다. 중간 조율에는 콘덕터가 끼어듭니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "Placement 사용자 문서", "url": "https://docs.openstack.org/placement/latest/user/index.html"}]');
